def _trajectory(x, target, x_test, t):
    from scipy.optimize import least_squares

    def basis(rates):
        return -np.expm1(-t[:, None] * rates)

    def residual(rates):
        b = basis(rates)
        return (b @ _fit(b, target.T) - target.T).ravel()
    rates = least_squares(residual, [0.4, 1.8], bounds=([0.01, 0.8], [0.8, 8.0])).x
    b = basis(rates)
    return x_test @ _fit(x, _fit(b, target.T).T) @ b.T

def _scalar_features(z):
    interaction = z[:, 0] * z[:, 2] + z[:, 1] * z[:, 3]
    return np.column_stack((_affine(z), interaction))

def _scalar(z, target, query):
    from scipy.optimize import least_squares
    (d, dq) = (_scalar_features(z), _scalar_features(query))

    def design(d, p):
        h = d @ p
        return np.column_stack((np.ones(len(h)), h, np.arctan(h)))

    def residual(p):
        a = design(d, p)
        return a @ _fit(a, target) - target
    init = _fit(d, target)
    opt = min((least_squares(residual, scale * init, max_nfev=150) for scale in (0.35, 0.7, 1.15, 1.6)), key=lambda r: r.cost)
    return design(dq, opt.x) @ _fit(design(d, opt.x), target)
